"""Fake chat models for tests (no real LLM is ever called)."""

import itertools
from collections.abc import Iterator
from typing import Any

from langchain_core.language_models.fake_chat_models import GenericFakeChatModel
from langchain_core.messages import AIMessage, BaseMessage
from pydantic import Field

_ids = itertools.count()


def tool_call(name: str, **args: Any) -> dict[str, Any]:
    return {"name": name, "args": args, "id": f"call_{next(_ids)}", "type": "tool_call"}


def ai(content: str = "", *calls: dict[str, Any]) -> AIMessage:
    return AIMessage(content=content, tool_calls=list(calls))


class FakeToolModel(GenericFakeChatModel):
    """GenericFakeChatModel that accepts bind_tools and records what it was sent."""

    received: list[list[BaseMessage]] = Field(default_factory=list)
    bound_tools: list[str] = Field(default_factory=list)

    def bind_tools(self, tools: Any, **kwargs: Any) -> "FakeToolModel":
        self.bound_tools = [getattr(t, "name", None) or t.get("name") for t in tools]
        return self

    def _generate(self, messages: list[BaseMessage], *args: Any, **kwargs: Any):
        self.received.append(list(messages))
        return super()._generate(messages, *args, **kwargs)

    @property
    def calls(self) -> int:
        return len(self.received)

    def human_texts(self) -> list[str]:
        return [m.text for msgs in self.received for m in msgs if m.type == "human"]


def scripted(*responses: AIMessage) -> FakeToolModel:
    return FakeToolModel(messages=iter(responses))


def endless(make: Any) -> FakeToolModel:
    """A model that answers every call with `make()`, forever."""

    def gen() -> Iterator[AIMessage]:
        while True:
            yield make()

    return FakeToolModel(messages=gen())
import pytest

import app.tools
from app.guardrails import LIMIT_REACHED_REPLY
from tests.fakes import ai, endless, scripted, tool_call

PII = {"name": "pii_redaction", "action": "redacted"}
LIMIT = {"name": "tool_call_limit", "action": "stopped"}


@pytest.fixture
def calc_counter(monkeypatch):
    """Counts how many times the calculator tool actually executed."""
    calls = []
    real = app.tools.evaluate

    def counting(expression):
        calls.append(expression)
        return real(expression)

    monkeypatch.setattr(app.tools, "evaluate", counting)
    return calls


def chat(client, message, session_id="s1"):
    return client.post("/chat", json={"session_id": session_id, "message": message})


# ------------------------------------------------------------------ basics


def test_health(make_client):
    r = make_client(scripted()).get("/health")
    assert r.status_code == 200
    assert r.json() == {"status": "ok"}


def test_plain_chat(make_client):
    model = scripted(ai("Hello there!"))
    r = chat(make_client(model), "Hi", session_id="abc")
    assert r.status_code == 200
    assert r.json() == {"session_id": "abc", "reply": "Hello there!", "guardrails": []}
    assert model.human_texts() == ["Hi"]


@pytest.mark.parametrize(
    "body",
    [
        {"message": "hi"},
        {"session_id": "s"},
        {"session_id": 1, "message": "hi"},
        {"session_id": "s", "message": None},
